HOST_ORDER = sys.byteorder


def map_enum_name_to_value(name):
    """SCMapEnumNameToValue(): case-insensitive, -1 when unknown."""
    if name is None:
        return -1
    for enum_name, enum_value in OS_POLICY_MAP:
        if enum_name.lower() == name.lower():
            return enum_value
    return -1


def canonical_flavour(name):
    """Canonical spelling of a valid flavour key, or None if invalid."""
    if name is None:
        return None
    for enum_name, _ in OS_POLICY_MAP:
        if enum_name.lower() == name.lower():
