    return None


# ---------------------------------------------------------------- util-cidr.c

def cidr_from_mask(netmask_be_bytes):
    """CIDRFromMask(): netmask arrives in network byte order.

    The C code does ntohl() first, so the value it walks is the mask read
    big-endian; that makes this host-endianness independent.
    """
    netmask = int.from_bytes(netmask_be_bytes, "big")
    if netmask == 0:
        return 0
    p = 0
    seen_1 = False
    while netmask > 0:
        if netmask & 1:
            seen_1 = True
            p += 1
        elif seen_1:
            return -1
        netmask >>= 1
    return p


def cidr_get(cidr):
    """CIDRGet(): returns the host-order uint32_t, i.e. htonl()'d mask."""
    if cidr <= 0 or cidr > 32:
        return 0
