    """CIDRGetIPv6(): the 16 mask bytes, replicating the C loop literally."""
    addr = bytearray(16)
    i = 0
    while cidr > 8 and i < 16:
        addr[i] = 0xFF
        cidr -= 8
        i += 1
    while cidr > 0 and i < 16:
        addr[i] |= 0x80
        cidr -= 1
        if cidr > 0:
            addr[i] >>= 1
    return bytes(addr)


