def mask_ip_netblock(stream, netmask):
    """MaskIPNetblock(): zero every address bit below the prefix length."""
    out = bytearray(stream)
    for i in range(len(out)):
        m = 0xFF
        if (i + 1) * 8 > netmask:
            if (i + 1) * 8 - netmask < 8:
                m = (0xFF << ((i + 1) * 8 - netmask)) & 0xFF
            else:
