    # matching SCConfGetNode("host-os-policy") in suricata.yaml.in.
    root = data
    if len(data) == 1:
        only = next(iter(data))
        if isinstance(only, str) and mangle(only) == "host-os-policy":
            inner = data[only]
            root = inner if isinstance(inner, dict) else {}

    out = {}
    for key, val in root.items():
        if not isinstance(key, str):
            continue
        if val is None:
            entries = []
        elif isinstance(val, list):
            entries = [str(v) for v in val if v is not None]
        elif isinstance(val, dict):
            continue
        else:
            entries = [str(val)]
        out[mangle(key)] = entries
    return out


def _parse_yaml_fallback(text):
    """Minimal reader for the flat "flavour: [a, b]" / block-list shape."""
    data = {}
    cur = None
    for raw_line in text.splitlines():
        line = raw_line.rstrip()
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        if line.strip() in ("---", "..."):
            continue
        if line.lstrip().startswith("%"):
            continue
        stripped = line.lstrip()
        indent = len(line) - len(stripped)

        if stripped.startswith("- "):
            if cur is not None:
                data[cur].append(_unquote(stripped[2:].strip()))
            continue
        if ":" not in stripped:
            continue
        key, _, rest = stripped.partition(":")
        # A mapping key here is a flavour name; addresses only appear as values.
        if indent == 0 or cur is None:
            key = _unquote(key.strip())
            rest = rest.strip()
            cur = key
            if rest.startswith("[") and rest.endswith("]"):
                body = rest[1:-1].strip()
                items = [_unquote(p.strip()) for p in body.split(",") if p.strip()]
                data[key] = items
                cur = None
            elif rest:
                data[key] = [_unquote(rest)]
                cur = None
            else:
                data[key] = []
    return data


def _unquote(s):
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "\"'":
        return s[1:-1]
    return s


def load_db(path):
    policies = parse_yaml(path)
