        for entry in entries:
            entry = entry.strip()
            if not entry:
                continue
            # SCHInfoLoadFromConfig(): family hint comes from ':' in the value.
            is_ipv4 = ":" not in entry
            db.add(flavour, entry, is_ipv4)
    return db


