USAGE = (
    "usage: ospolicy cidr ipv4-mask <dotted-quad>\n"
    "       ospolicy cidr ipv4-prefix <n>\n"
    "       ospolicy cidr ipv6-prefix <n>\n"
    "       ospolicy load <yaml-path>   (IPs on stdin, one per line)\n"
)


def cmd_cidr(args):
    if len(args) != 2:
        sys.stderr.write(USAGE)
        return 2
    what, value = args

    if what == "ipv4-mask":
        try:
            raw = socket.inet_pton(socket.AF_INET, value)
        except (OSError, ValueError, UnicodeEncodeError):
            sys.stderr.write("invalid netmask\n")
            return 1
        print(cidr_from_mask(raw))
        return 0

    if what in ("ipv4-prefix", "ipv6-prefix"):
        try:
            n = int(value, 10)
        except ValueError:
            sys.stderr.write("invalid prefix length\n")
            return 1
        if what == "ipv4-prefix":
            print("%08x" % cidr_get(n))
        else:
            print(cidr_get_ipv6(n).hex())
        return 0

    sys.stderr.write(USAGE)
    return 2


def cmd_load(args):
    if len(args) != 1:
        sys.stderr.write(USAGE)
        return 2
    try:
        db = load_db(args[0])
    except DuplicateAddress:
        sys.stderr.write("duplicate\n")
        return 1
    except InvalidAddress as exc:
        sys.stderr.write("invalid address '%s'\n" % (exc.args[0] if exc.args else "",))
        return 1
    except OSError as exc:
        sys.stderr.write("cannot read policy: %s\n" % exc)
        return 1

    for line in sys.stdin:
        ip = line.strip()
        if not ip:
            continue
        sys.stdout.write("%s %s\n" % (ip, db.lookup(ip)))
    return 0


def main(argv):
    if len(argv) < 2:
        sys.stderr.write(USAGE)
        return 2
    cmd, args = argv[1], argv[2:]
    if cmd == "cidr":
        return cmd_cidr(args)
    if cmd == "load":
        return cmd_load(args)
    sys.stderr.write(USAGE)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))

